        let currentBucketConfig = null;
        let draggedFunction = null;

        function getBucketStorageKey() {
            const fc = window.getWarehouseId() || 'LEJ5';
            return 'bucketConfig_' + fc;
        }

        function loadBucketConfig() {
            const key = getBucketStorageKey();
            const saved = localStorage.getItem(key);
            if (saved) {
                try {
                    const parsed = JSON.parse(saved);
                    /* The stored value is now shared across the site rather
                       than private to one browser, so a single bad write
                       would otherwise take Shift Pulse down for everybody on
                       the FC. Anything that is not a usable bucket list is
                       ignored in favour of the defaults. */
                    if (parsed && Array.isArray(parsed.buckets)) {
                        parsed.buckets = parsed.buckets.filter(function (b) {
                            return b && typeof b === 'object';
                        }).map(function (b) {
                            return {
                                id: b.id || ('bucket_' + Math.random().toString(36).slice(2, 8)),
                                name: b.name || 'Unnamed',
                                functions: Array.isArray(b.functions) ? b.functions.filter(function (f) {
                                    return f && f.name;
                                }) : []
                            };
                        });
                        return parsed;
                    }
                    console.warn('Saved bucket config has no buckets; using defaults:', parsed);
                } catch (e) {
                    console.warn('Failed to parse saved bucket config:', e);
                }
            }
            return JSON.parse(JSON.stringify(DEFAULT_BUCKET_CONFIG));
        }

        function saveBucketConfig() {
            const key = getBucketStorageKey();
            localStorage.setItem(key, JSON.stringify(currentBucketConfig));
            alert('✅ Bucket configuration saved for ' + (window.getWarehouseId() || 'LEJ5'));
            // Notify data provider that config changed
            document.dispatchEvent(new CustomEvent('bucketConfigChanged', { detail: currentBucketConfig }));
            // Refresh target settings table
            document.dispatchEvent(new CustomEvent('renderTargets'));
        }

        function resetBucketConfig() {
            if (confirm('Reset bucket configuration to defaults?')) {
                const key = getBucketStorageKey();
                localStorage.removeItem(key);
                currentBucketConfig = JSON.parse(JSON.stringify(DEFAULT_BUCKET_CONFIG));
                renderBucketConfig();
                alert('✅ Bucket configuration reset to defaults');
                document.dispatchEvent(new CustomEvent('bucketConfigChanged', { detail: currentBucketConfig }));
            }
        }

        function getAssignedFunctions() {
            const assigned = new Set();
            currentBucketConfig.buckets.forEach(bucket => {
                bucket.functions.forEach(fn => assigned.add(fn.name));
            });
            return assigned;
        }

        function renderFunctionPool() {
            const assigned = getAssignedFunctions();
            
            ['admin', 'facilities', 'nonfc'].forEach(processKey => {
                const container = document.getElementById(processKey + 'Functions');
                if (!container) return;
                
                container.innerHTML = '';
                const processFunctions = ALL_FUNCTIONS.filter(f => f.process === processKey);
                
                // Sort by hours descending
                processFunctions.sort((a, b) => (b.hours || 0) - (a.hours || 0));
                
                processFunctions.forEach(fn => {
                    const isAssigned = assigned.has(fn.name);
                    
                    const div = document.createElement('div');
                    div.className = 'function-item' + (isAssigned ? ' assigned' : '');
                    div.draggable = !isAssigned;
                    div.dataset.function = fn.name;
                    div.dataset.process = fn.process;
                    
                    const tagClass = fn.process === 'admin' ? 'admin' : fn.process === 'facilities' ? 'facilities' : 'nonfc';
                    const tagText = fn.process === 'admin' ? 'Admin' : fn.process === 'facilities' ? 'Fac' : 'NonFC';
                    
                    // Show hours if available
                    const hoursDisplay = fn.hours ? `<span class="function-hours">${Math.round(fn.hours)}h</span>` : '';
                    
                    div.innerHTML = `${fn.name}${hoursDisplay} <span class="process-tag ${tagClass}">${tagText}</span>${isAssigned ? ' <span style="color:#999;font-size:8px;">✓</span>' : ''}`;
                    
                    if (!isAssigned) {
                        div.addEventListener('dragstart', handleDragStart);
                        div.addEventListener('dragend', handleDragEnd);
                    }
                    
                    container.appendChild(div);
                });
            });
        }

        function renderBuckets() {
            const container = document.getElementById('bucketsContainer');
            if (!container) return;
            
            container.innerHTML = '';
            
            currentBucketConfig.buckets.forEach((bucket, index) => {
                const bucketDiv = document.createElement('div');
                bucketDiv.className = 'bucket';
                bucketDiv.dataset.bucketIndex = index;
                
                bucketDiv.innerHTML = `
                    <div class="bucket-header">
                        <input type="text" class="bucket-name-input" value="${bucket.name}" 
                               onchange="updateBucketName(${index}, this.value)">
                        <div class="bucket-actions">
                            <button class="bucket-action-btn" onclick="deleteBucket(${index})" title="Delete bucket">🗑️</button>
                        </div>
                    </div>
                    <div class="bucket-content ${bucket.functions.length === 0 ? 'empty' : ''}" data-bucket-index="${index}">
                        ${bucket.functions.map((fn, fnIndex) => `
                            <div class="bucket-function" draggable="true" data-function="${fn.name}" data-process="${fn.process}" data-fn-index="${fnIndex}">
                                ${fn.name}
                                <span class="remove-btn" onclick="removeFunctionFromBucket(${index}, ${fnIndex})">×</span>
                            </div>
                        `).join('')}
                    </div>
                `;
                
                // Add drag events to bucket content
                const content = bucketDiv.querySelector('.bucket-content');
                content.addEventListener('dragover', handleDragOver);
                content.addEventListener('dragleave', handleDragLeave);
                content.addEventListener('drop', handleDrop);
                
                // Add drag events to functions in bucket
                bucketDiv.querySelectorAll('.bucket-function').forEach(fn => {
                    fn.addEventListener('dragstart', handleDragStart);
                    fn.addEventListener('dragend', handleDragEnd);
                });
                
                container.appendChild(bucketDiv);
            });
            
            // Add "Add Bucket" button
            const addBtn = document.createElement('div');
            addBtn.className = 'add-bucket-btn';
            addBtn.innerHTML = '➕ Add Bucket';
            addBtn.onclick = addNewBucket;
            container.appendChild(addBtn);
        }

        function renderBucketConfig() {
            renderFunctionPool();
            renderBuckets();
        }

        function handleDragStart(e) {
            draggedFunction = {
                name: e.target.dataset.function,
                process: e.target.dataset.process,
                fromBucket: e.target.closest('.bucket-content')?.dataset.bucketIndex,
                fnIndex: e.target.dataset.fnIndex
            };
            e.target.classList.add('dragging');
            e.dataTransfer.effectAllowed = 'move';
        }

        function handleDragEnd(e) {
            e.target.classList.remove('dragging');
            document.querySelectorAll('.bucket').forEach(b => b.classList.remove('drag-over'));
            draggedFunction = null;
        }

        function handleDragOver(e) {
            e.preventDefault();
            e.dataTransfer.dropEffect = 'move';
            e.currentTarget.closest('.bucket')?.classList.add('drag-over');
        }

        function handleDragLeave(e) {
            e.currentTarget.closest('.bucket')?.classList.remove('drag-over');
        }

        function handleDrop(e) {
            e.preventDefault();
            const bucketContent = e.currentTarget;
            const targetBucketIndex = parseInt(bucketContent.dataset.bucketIndex);
            
            bucketContent.closest('.bucket')?.classList.remove('drag-over');
            
            if (!draggedFunction) return;
            
            // Remove from source bucket if it came from one
            if (draggedFunction.fromBucket !== undefined) {
                const sourceBucketIndex = parseInt(draggedFunction.fromBucket);
                const fnIndex = parseInt(draggedFunction.fnIndex);
                currentBucketConfig.buckets[sourceBucketIndex].functions.splice(fnIndex, 1);
            }
            
            // Add to target bucket
            currentBucketConfig.buckets[targetBucketIndex].functions.push({
                name: draggedFunction.name,
                process: draggedFunction.process
            });
            
            renderBucketConfig();
        }

        function updateBucketName(index, newName) {
            currentBucketConfig.buckets[index].name = newName;
        }

        function deleteBucket(index) {
            if (confirm('Delete this bucket? Functions will return to the pool.')) {
                currentBucketConfig.buckets.splice(index, 1);
                renderBucketConfig();
            }
        }

        function removeFunctionFromBucket(bucketIndex, fnIndex) {
            currentBucketConfig.buckets[bucketIndex].functions.splice(fnIndex, 1);
            renderBucketConfig();
        }

        function addNewBucket() {
            const newId = 'custom_' + Date.now();
            currentBucketConfig.buckets.push({
                id: newId,
                name: 'New Bucket',
                functions: []
            });
            renderBucketConfig();
        }

        // Expose getBucketConfig globally for data provider
        // Returns current in-memory config (which may have unsaved changes) or loads from storage
        window.getBucketConfig = function() {
            // If we have a current config in memory, return it (includes unsaved changes)
            if (currentBucketConfig && currentBucketConfig.buckets && currentBucketConfig.buckets.length > 0) {
                return currentBucketConfig;
            }
            // Otherwise load from storage
            const loaded = loadBucketConfig();
            return loaded;
        };

        // Expose process map globally
        window.getProcessMap = function() {
            return PROCESS_MAP;
        };

        // Discovered functions storage (with hours from last month)
        let discoveredFunctions = {};

        // Build monthly FRU URL for last full month
        function buildMonthlyFRUUrl(processId) {
            const fc = window.getWarehouseId() || 'LEJ5';
            const now = new Date();
            // Get first day of last month
            const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
            const monthStr = `${lastMonth.getFullYear()}/${String(lastMonth.getMonth() + 1).padStart(2, '0')}/01`;
            return `https://fclm-portal.amazon.com/reports/functionRollup?reportFormat=HTML&warehouseId=${fc}&processId=${processId}&spanType=Month&startDateMonth=${encodeURIComponent(monthStr)}&maxIntradayDays=1&startHourIntraday=0&startMinuteIntraday=0&endHourIntraday=0&endMinuteIntraday=0`;
        }

        // Parse functions and hours from FRU HTML
        function parseFunctionsFromFRU(html, processKey) {
            const parser = new DOMParser();
            const doc = parser.parseFromString(html, 'text/html');
            const functions = [];
            
            // Find all function tables (they have captions with function names)
            const tables = doc.querySelectorAll('table');
            
            tables.forEach(table => {
                const caption = table.querySelector('caption');
                if (!caption) return;
                
                const captionText = caption.textContent.trim();
                // Extract function name (before the [id])
                const functionName = captionText.split('[')[0].trim();
                if (!functionName) return;
                
                // Find the total row to get hours
                const totalRow = table.querySelector('tr.total, tr.empl-all.total');
                let hours = 0;
                
                if (totalRow) {
                    // Look for the Paid Hours Total cell (usually has class "size-total" without "numeric")
                    const sizeTotalCells = totalRow.querySelectorAll('td.size-total:not(.numeric)');
                    if (sizeTotalCells.length > 0) {
                        const hrsText = sizeTotalCells[0].textContent.trim().replace(/,/g, '');
                        hours = parseFloat(hrsText) || 0;
                    }
                }
                
                // Only include functions with actual hours
                if (hours > 0) {
                    functions.push({
                        name: functionName,
                        process: processKey,
                        hours: hours
                    });
                }
            });
            
            return functions;
        }

        // Discover functions from FCLM
        async function discoverFunctions() {
            const btn = document.getElementById('discoverFunctionsBtn');
            const status = document.getElementById('discoverStatus');
            const fc = window.getWarehouseId();
            const monthSelect = document.getElementById('discoverMonthSelect');
            const monthPeriod = monthSelect ? monthSelect.value : 'last'; // 'last' or 'current'
            
            if (!fc) {
                alert('⚠️ Please enter FC code first!');
                return;
            }
            
            const periodLabel = monthPeriod === 'current' ? 'current month' : 'last month';
            
            btn.disabled = true;
            btn.textContent = '⏳ Loading...';
            status.style.display = 'block';
            status.textContent = `Fetching function data from FCLM for ${periodLabel}...`;
            
            const processIds = {
                admin: '01002960',
                facilities: '01003028',
                nonfc: '01003047'
            };
            
            discoveredFunctions = {};
            
            try {
                // Dispatch event to data provider to fetch the data
                const results = await new Promise((resolve, reject) => {
                    const handler = function(e) {
                        document.removeEventListener('discoverFunctionsResult', handler);
                        if (e.detail.error) {
                            reject(new Error(e.detail.error));
                        } else {
                            resolve(e.detail.functions);
                        }
                    };
                    document.addEventListener('discoverFunctionsResult', handler);
                    
                    // Request data from data provider with month period selection
                    document.dispatchEvent(new CustomEvent('discoverFunctionsRequest', {
                        detail: { processIds, fc, monthPeriod }
                    }));
                    
                    // Timeout after 30 seconds
                    setTimeout(() => {
                        document.removeEventListener('discoverFunctionsResult', handler);
                        reject(new Error('Timeout waiting for FCLM data'));
                    }, 30000);
                });
                
                discoveredFunctions = results;
                
                // Update ALL_FUNCTIONS with discovered functions
                updateAllFunctionsFromDiscovery(results);
                
                // Re-render the function pool
                renderFunctionPool();
                
                const totalFunctions = Object.values(results).flat().length;
                const now = new Date();
                const targetMonth = monthPeriod === 'current'
                    ? new Date(now.getFullYear(), now.getMonth(), 1)
                    : new Date(now.getFullYear(), now.getMonth() - 1, 1);
                const monthName = targetMonth.toLocaleString('en-US', { month: 'long', year: 'numeric' });
                
                status.style.background = '#d4edda';
                status.textContent = `✅ Found ${totalFunctions} functions with hours in ${monthName}`;
                
            } catch (error) {
                console.error('Error discovering functions:', error);
                status.style.background = '#f8d7da';
                status.textContent = `❌ Error: ${error.message}`;
            } finally {
                btn.disabled = false;
                btn.textContent = '🔍 Discover from FCLM';
            }
        }

        // Update ALL_FUNCTIONS array with discovered functions
        function updateAllFunctionsFromDiscovery(discovered) {
            // Create a map of existing functions
            const existingMap = new Map(ALL_FUNCTIONS.map(f => [f.name, f]));
            
            // Add/update with discovered functions
            Object.entries(discovered).forEach(([processKey, functions]) => {
                functions.forEach(fn => {
                    if (existingMap.has(fn.name)) {
                        // Update hours for existing function
                        existingMap.get(fn.name).hours = fn.hours;
                    } else {
                        // Add new function
                        ALL_FUNCTIONS.push({
                            name: fn.name,
                            process: processKey,
                            hours: fn.hours
                        });
                    }
                });
            });
            
            // Sort by hours descending within each process
            ALL_FUNCTIONS.sort((a, b) => (b.hours || 0) - (a.hours || 0));
        }

        // Initialize bucket config
        currentBucketConfig = loadBucketConfig();
        renderBucketConfig();

        // Function to update indirect table headers based on bucket config
        function updateIndirectTableHeaders() {
            const thead = document.getElementById('indirectTableHead');
            if (!thead) return;
            
            // Use currentBucketConfig if available (includes unsaved changes), otherwise load from storage
            const config = (currentBucketConfig && currentBucketConfig.buckets) ? currentBucketConfig : loadBucketConfig();
            const buckets = config.buckets;
            
            // Build header rows
            let row1 = '<tr><th rowspan="2">Time</th>';
            let row2 = '<tr>';
            
            buckets.forEach(bucket => {
                row1 += `<th colspan="3">${bucket.name}</th>`;
                row2 += '<th>Hrs</th><th>Target</th><th>Diff</th>';
            });
            
            row1 += '</tr>';
            row2 += '</tr>';
            
            thead.innerHTML = row1 + row2;
            
            // Update tfoot column count
            const tfoot = thead.closest('table')?.querySelector('tfoot');
            if (tfoot) {
                updateIndirectTableFooter(buckets);
            }
        }
        
        function updateIndirectTableFooter(buckets) {
            const tfoot = document.querySelector('#hourlyTableBody')?.closest('table')?.querySelector('tfoot');
            if (!tfoot) return;
            
            let footerHtml = '<tr><td>TOTAL</td>';
            buckets.forEach(bucket => {
                const idBase = bucket.id.replace(/([A-Z])/g, (m) => m).replace(/^./, (m) => m.charAt(0).toUpperCase() + m.slice(1));
                footerHtml += `<td id="total${bucket.id}">0</td><td id="total${bucket.id}Target">0</td><td id="total${bucket.id}Diff">-</td>`;
            });
            footerHtml += '</tr>';
            tfoot.innerHTML = footerHtml;
        }

        // Update headers when bucket config changes
        document.addEventListener('bucketConfigChanged', function() {
            updateIndirectTableHeaders();
        });

        // Reload bucket config when FC changes
        document.getElementById('fcInput').addEventListener('change', function() {
            currentBucketConfig = loadBucketConfig();
            renderBucketConfig();
            updateIndirectTableHeaders();
        });

        console.log('✓ Dashboard initialized');
        console.log('✓ getWarehouseId available globally');
        console.log('✓ Collapsible sections enabled');
        console.log('✓ Shift settings available');
        console.log('✓ Bucket configuration available');
    

